\title{Tightness of the Isolation Lemma Bound\\ Under Arbitrary Edge Offsets}
\author{Aristotle}
\date{July 12, 2026}

\begin{document}
\maketitle

\begin{abstract}
The Isolation Lemma of Mulmuley, Vazirani, and Vazirani (1987) guarantees that a
random weighting of the ground set of a set system isolates, with high
probability, a unique minimum-weight member. In the exact counting refinement
studied by Faber and Harris, one asks for the number of isolating weight
assignments $w \in \{0,\dots,d-1\}^n$ for an inclusion-free (Sperner) hypergraph,
and this number is bounded below by $n\sum_{j=0}^{d-1} j^{\,n-1}$. The singleton
hypergraph attains this bound exactly with zero offset. We analyze what happens
under an \emph{arbitrary integer edge offset} $f$, where the singleton edge
$\{i\}$ carries weight $f_i + w_i$. Our main result is an exact product--sum
identity for the isolating count valid for \emph{every} offset. From it we obtain
the two extreme regimes exactly: constant offsets reproduce the Faber--Harris
extremal value $n\sum_{j<d} j^{\,n-1}$ (the offset-free floor), while widely
separated offsets isolate every assignment and reach the maximum $d^n$. In
particular the extremal value is \emph{not} an offset invariant: the offset
$f=(0,1,5)$ on $(n,d)=(3,3)$ yields $21 > 15$ isolating assignments. We give the
supporting structural lemmas, numerical corroboration, algorithms, and a program
of four conjectures.
\end{abstract}

\section{Introduction}

\subsection{Background}
Let $V = \{1,\dots,n\}$ be a ground set and let $H$ be a hypergraph on $V$: a
family of edges $S \subseteq V$. A \emph{weight assignment} is a map
$w : V \to \{0,1,\dots,d-1\}$; we write $[d] = \{0,\dots,d-1\}$, and there are
$d^n$ assignments. Given an \emph{edge offset} $f : H \to \mathbb{R}$, each edge
$S$ receives weight
\[
  W_f(S, w) = f(S) + \sum_{v\in S} w(v).
\]
The assignment $w$ is \emph{isolating} if a unique edge attains the minimum
weight $\min_{S\in H} W_f(S,w)$. A hypergraph is \emph{inclusion-free} (a Sperner
family / antichain) if no edge is a proper subset of another. Faber and Harris
established the sharp lower bound
\[
  \#\{\text{isolating } w\} \;\geq\; n\sum_{j=0}^{d-1} j^{\,n-1}
  \qquad\text{for every inclusion-free } H.
\]

\subsection{The singleton hypergraph and the offset question}
The \emph{singleton hypergraph} is $H = \{\{1\},\dots,\{n\}\}$; here
$W_f(\{i\}, w) = f_i + w_i$, so isolation is the event that a single vertex
attains the strict minimum of $i \mapsto f_i + w_i$. With zero offset the
singleton hypergraph meets the Faber--Harris bound with equality. This paper
treats integer offsets $f : V \to \mathbb{Z}$ (an order-faithful subfamily of the
real offsets, since isolation depends only on the linear order of the finitely
many edge weights) and determines the isolating count for every such offset.

\section{Definitions}
Fix integers $n \geq 0$ and $d \geq 1$. Assignments are maps $w : V \to [d]$ and
an offset is a map $f : V \to \mathbb{Z}$.

\begin{definition}[Offset weight]
The weight of the singleton edge $\{i\}$ under offset $f$ and assignment $w$ is
$g_f(w, i) = f_i + w_i \in \mathbb{Z}$.
\end{definition}

\begin{definition}[Isolating assignment]
$w$ is \emph{isolating for $f$} if a unique vertex attains the minimum offset
weight: $\exists!\, i \; \forall j,\; g_f(w,i)\le g_f(w,j)$.
\end{definition}

\begin{definition}[Strict minimum]
$w$ \emph{has a strict minimum for $f$} if
$\exists\, i \; \forall j\neq i,\; g_f(w,i) < g_f(w,j)$.
\end{definition}

\begin{definition}[Isolating set and count]
$\mathcal I_f = \{\,w\in[d]^n : w \text{ has a strict minimum for } f\,\}$, with
isolating count $I(n,d,f) = |\mathcal I_f|$.
\end{definition}

\begin{definition}[Strict-min-at-$i$ set]
For a vertex $i$, $\mathcal M_f(i) = \{\,w\in[d]^n : \forall j\neq i,\ g_f(w,i) <
g_f(w,j)\,\}$.
\end{definition}

\begin{definition}[Above-threshold count]
For vertices $i,j$ and a value $m\in[d]$,
$A_f(i,j,m) = \#\{\,k\in[d] : f_i + m < f_j + k\,\}
 = \min\!\bigl(d,\ \max(0,\ d - 1 - (f_i + m - f_j))\bigr)$.
\end{definition}

\section{Main Results}

\begin{lemma}[Isolation equals strict minimum]\label{lem:iso}
For every offset $f$ and assignment $w$,
$\bigl(\exists!\, i\ \forall j,\ g_f(w,i)\le g_f(w,j)\bigr) \iff
 \bigl(\exists\, i\ \forall j\neq i,\ g_f(w,i) < g_f(w,j)\bigr)$.
\end{lemma}
\begin{proof}[Proof sketch]
($\Rightarrow$) Let $i$ be the unique minimizer. For $j\neq i$, either
$g_f(w,i) < g_f(w,j)$ or $g_f(w,i) = g_f(w,j)$; in the latter case $j$ is a
second minimizer, contradicting uniqueness. ($\Leftarrow$) A strict minimizer $i$
is a minimizer; any other minimizer $k\neq i$ satisfies $g_f(w,k)\le g_f(w,i)$,
contradicting strictness $g_f(w,i) < g_f(w,k)$. Hence $i$ is unique.
\end{proof}

\begin{lemma}[Fiber count]\label{lem:fiber}
Fix $i$ and $m\in[d]$. Then
\[
  \#\{\,w : w_i = m,\ \forall j\neq i,\ f_i + m < f_j + w_j\,\}
  = \prod_{j\neq i} A_f(i,j,m).
\]
\end{lemma}
\begin{proof}[Proof sketch]
Fixing $w_i = m$, each remaining coordinate $w_j$ ranges independently over
$\{k\in[d] : f_i + m < f_j + k\}$, of size $A_f(i,j,m)$. The fiber is the product
of these independent choices, so its cardinality is the product of the factor
sizes.
\end{proof}

\begin{lemma}[Strict-min-at-$i$ count]\label{lem:strictmin}
For each vertex $i$,
$|\mathcal M_f(i)| = \sum_{m=0}^{d-1}\ \prod_{j\neq i} A_f(i,j,m)$.
\end{lemma}
\begin{proof}[Proof sketch]
Partition $\mathcal M_f(i)$ by the value $m = w_i$ of the minimizing vertex. The
pieces are the fibers of Lemma~\ref{lem:fiber} and are pairwise disjoint; summing
their counts gives the claim.
\end{proof}

\begin{lemma}[Argmin decomposition]\label{lem:argmin}
$\mathcal I_f = \bigsqcup_{i=1}^{n} \mathcal M_f(i)$, hence
$I(n,d,f) = \sum_{i=1}^{n} |\mathcal M_f(i)|$.
\end{lemma}
\begin{proof}[Proof sketch]
$\mathcal I_f = \bigcup_i \mathcal M_f(i)$ by definition. If $w$ had two strict
minima $i\neq i'$ then $g_f(w,i) < g_f(w,i')$ and $g_f(w,i') < g_f(w,i)$, a
contradiction; so the union is disjoint and cardinalities add.
\end{proof}

\begin{theorem}[Exact isolating count under an arbitrary offset]\label{thm:master}
For the singleton hypergraph on $n$ vertices with palette $[d]$ and any integer
offset $f$,
\[
  I(n,d,f) \;=\; \sum_{i=1}^{n}\ \sum_{m=0}^{d-1}\ \prod_{j\neq i}
  \#\{\,k\in[d] : f_i + m < f_j + k\,\}.
\]
\end{theorem}
\begin{proof}
Combine Lemma~\ref{lem:argmin} (decompose over the argmin vertex), Lemma
\ref{lem:strictmin} (expand each $|\mathcal M_f(i)|$ over the minimum value $m$),
and Lemma~\ref{lem:fiber} (factor each fiber). Lemma~\ref{lem:iso} equates this
strict-minimum count with the $\exists!$-isolating count.
\end{proof}

\begin{lemma}[Constant offset reduces to the offset-free notion]\label{lem:const}
For any constant $c\in\mathbb{Z}$, $w$ has a strict minimum for $f\equiv c$ iff it
has a strict minimum in the offset-free sense.
\end{lemma}
\begin{proof}[Proof sketch]
$g_c(w,i) = c + w_i$, so $g_c(w,i) < g_c(w,j) \iff w_i < w_j$; the constant
cancels.
\end{proof}

\begin{theorem}[Constant offsets recover the Faber--Harris value]\label{thm:const}
For every constant offset $f\equiv c$,
$\; I(n,d,c) = n\sum_{j=0}^{d-1} j^{\,n-1}$.
\end{theorem}
\begin{proof}
With $f$ constant, $A_f(i,j,m) = \#\{k : m < k\} = d-1-m$, so by
Theorem~\ref{thm:master}
\[
  I = \sum_{i=1}^n \sum_{m=0}^{d-1} (d-1-m)^{n-1}
    = n\sum_{m=0}^{d-1}(d-1-m)^{n-1}
    = n\sum_{j=0}^{d-1} j^{\,n-1},
\]
reindexing $j = d-1-m$. Equivalently, by Lemma~\ref{lem:const} the isolating set
equals the offset-free one.
\end{proof}

\begin{theorem}[Widely separated offsets isolate everything]\label{thm:sep}
If the offsets are pairwise separated by at least the palette width (e.g.
$f_i = i\cdot d$), then every assignment is isolating: $I(n,d,f) = d^n$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $i^\star$ minimize $f$. For any $w$, $g_f(w,i^\star) \le f_{i^\star} + (d-1) <
f_j \le g_f(w,j)$ for all $j\neq i^\star$ by separation, so $i^\star$ is a strict
minimum for every $w$; hence $\mathcal I_f = [d]^n$. Via
Theorem~\ref{thm:master}, separation forces $A_f(i^\star,j,m) = d$, so the
$i^\star$-term alone contributes $\sum_m d^{n-1} = d^n$.
\end{proof}

\begin{theorem}[The extremal value is not an offset invariant]\label{thm:witness}
There exist $n,d,f$ with $I(n,d,f) > n\sum_{j<d} j^{n-1}$; explicitly
$I\bigl(3,3,(0,1,5)\bigr) = 21 > 15 = 3\sum_{j=0}^{2} j^{2}$.
\end{theorem}
\begin{proof}
Direct evaluation of Theorem~\ref{thm:master} (equivalently, enumeration of all
$27$ assignments) gives $21$; the offset-free value is $3(0+1+4)=15$.
\end{proof}

Combining Theorems~\ref{thm:const}, \ref{thm:sep}, and \ref{thm:witness}, the
isolating count of the singleton hypergraph lies in the band
\[
  n\sum_{j=0}^{d-1} j^{\,n-1} \;\le\; I(n,d,f) \;\le\; d^n,
\]
with the floor realized by constant offsets and the ceiling by separated ones.

\section{Algorithms}
Evaluating Theorem~\ref{thm:master} directly costs $O(n^2 d)$ operations:
each above-threshold count is $O(1)$ via the closed form for $A_f$, and there are
$n\cdot d$ products of $n-1$ factors. This is exponentially faster than the
$O(n\,d^n)$ brute-force enumeration used for validation. A spectrum explorer
tabulates $I(n,d,f)$ over a bounded offset lattice, recording the minimum
(constant), maximum (separated), and intermediate values hit.

\section{Numerical Corroboration}
All values were computed by Theorem~\ref{thm:master} and confirmed by
brute-force enumeration.
\begin{center}
\begin{tabular}{cccl}
\toprule
$(n,d)$ & offset $f$ & $I(n,d,f)$ & note \\
\midrule
$(3,3)$ & $(0,0,0)$ & $15$ & floor $= 3\sum_{j<3} j^2$ \\
$(3,3)$ & $(0,1,5)$ & $21$ & strictly above floor \\
$(3,4)$ & $(2,2,2)$ & $42$ & any constant $\Rightarrow$ floor \\
$(3,4)$ & $(0,4,8)$ & $64 = 4^3$ & separated $\Rightarrow$ ceiling \\
\bottomrule
\end{tabular}
\end{center}

\section{Applications and Discussion}
The Isolation Lemma underpins parallel matching algorithms and complexity-theoretic
reductions; its counting refinement quantifies how many random weightings succeed.
Real instances carry structural biases, modeled as edge offsets. Our results show
these biases move the isolating count predictably: it never drops below the
symmetric floor and never exceeds $d^n$, and both endpoints have transparent
combinatorial meaning. Theorem~\ref{thm:master} converts a global extremal
statement into a local, hand-computable one governed by the single scalar
$A_f(i,j,m)$.

\section{Future Directions}

\begin{conjecture}[Offset monotonicity]
The isolating count is minimized exactly at constant offsets: every integer offset
$f$ satisfies $I(n,d,f) \ge n\sum_{j<d} j^{n-1}$, with equality iff $f$ is
constant. Spreading offsets apart can only break ties in favor of a unique
minimizer, so the master identity reduces the claim to a term-by-term comparison
against the symmetric baseline.
\end{conjecture}

\begin{conjecture}[Full offset spectrum]
As $f$ ranges over all integer offsets, $I(n,d,f)$ takes every integer value in
$[\,n\sum_{j<d} j^{n-1},\ d^n\,]$ and none outside it. The endpoints are realized
by constant and separated offsets; interpolating one coordinate at a time sweeps
the interval.
\end{conjecture}

\begin{conjecture}[General hypergraphs attain the floor via offsets]
For every inclusion-free hypergraph $H$ on $n$ vertices there is an edge offset
$f$ with isolating count exactly $n\sum_{j<d} j^{n-1}$. A suitable offset makes
every edge except a minimal spanning skeleton non-competitive, reducing $H$ to the
singleton hypergraph.
\end{conjecture}

\begin{conjecture}[Real versus integer offsets]
The isolating-count values achievable with real offsets coincide with those
achievable with integer offsets. Isolation depends only on the linear order of the
finitely many edge weights, so any real offset can be perturbed to a rational and
cleared to an integer without crossing a comparison boundary.
\end{conjecture}

\section{Conclusion}
For the singleton hypergraph we determined the isolating count under an arbitrary
integer edge offset by an exact product--sum identity, and pinned its two extreme
regimes: constant offsets reproduce the Faber--Harris extremal value
$n\sum_{j<d} j^{n-1}$, while widely separated offsets reach $d^n$. The extremal
value is therefore not an offset invariant, as the offset $(0,1,5)$ on $(3,3)$
already shows ($15 \to 21$).

