from typing import Sequence

def above_threshold(d: int, fi: int, m: int, fj: int) -> int:
    return min(d, max(0, d - 1 - (fi + m - fj)))

def isolating_count_formula(n: int, d: int, f: Sequence[int]) -> int:
    total = 0
    for i in range(n):
        for m in range(d):
            prod = 1
            for j in range(n):
                if j == i:
                    continue
                prod *= above_threshold(d, f[i], m, f[j])
            total += prod
    return total

def offset_spectrum(n: int, d: int, lo: int, hi: int) -> dict[str, object]:
    """Sweep integer offsets in [lo, hi]^n and report the achieved count band.

    Returns the theoretical floor n*sum j^(n-1), the ceiling d^n, the set of
    distinct counts observed, and whether every observed count lies in the band.
    Complexity: O((hi-lo+1)^n * n^2 * d).
    """
    floor = n * sum(j ** (n - 1) for j in range(d))
    ceiling = d ** n
    seen: set[int] = set()
    for f in product(range(lo, hi + 1), repeat=n):
        seen.add(isolating_count_formula(n, d, list(f)))
    return {
        "floor": floor,
        "ceiling": ceiling,
        "distinct_counts": sorted(seen),
        "all_in_band": all(floor <= v <= ceiling for v in seen),
    }
